```go
package main
import (
 "fmt"
 "strings"
)
func main() {
 sentence := "The quick brown fox jumps over the lazy dog and the cat is sleeping on the mat."
 questionTypes := []string{"What", "Where", "Who", "When", "Why", "How"}
 // Split sentence into clauses
 clauses := strings.Split(sentence, " and ")
 // Loop through each clause
 for i, clause := range clauses {
 // Trim leading/trailing whitespace
 clause = strings.TrimSpace(clause)
 // Check if clause ends with a period
 if strings.HasSuffix(clause, ".") {
 // Remove period
 clause = clause[:len(clause)-1]
 }
 // Split clause into words
 words := strings.Split(clause, " ")
 // Check if first word is a question word
 for _, questionType := range questionTypes {
 if words[0] == questionType {
 // Print clause as is
 fmt.Printf("Clause %d: %sn", i+1, clause)
 break
 }
 }
 // Check if clause is a statement
 if words[0] != "Is" && words[0] != "Are" {
 // Convert clause to "What" question
 question := "What " + clause + "?"
 fmt.Printf("Clause %d: %sn", i+1, question)
 } else {
 // Convert clause to "Yes/No" question
 question := strings.Join(words[1:], " ") + "?"
 fmt.Printf("Clause %d: %sn", i+1, question)
 }
 }
}
```
This code first splits the sentence into clauses using the conjunction "and". It then loops through each clause and checks if it is a question or a statement. If the clause starts with a question word, it is printed as is. If it is a statement, it is converted to a "What" question by appending a question mark to the end. If the statement starts with "Is" or "Are", it is converted to a "Yes/No" question by removing the first word and appending a question mark to the end. Finally, each clause is printed with its corresponding question type.

