import Foundation
let initialVelocity: Double = 50 // m/s
let angle: Double = 45 // degrees
let dragCoefficient: Double = 0.3
let crossSectionalArea: Double = 0.2 // m^2
let molecularMassOfAir: Double = 0.02897 // kg/mol
let gasConstant: Double = 8.314 // J/mol*K
let initialAltitude: Double = 0 // m
let airDensityAtSeaLevel: Double = 1.225 // kg/m^3
let pressureAtSeaLevel: Double = 101325 // Pa
let temperatureAtSeaLevel: Double = 288 // K
let gravitationalConstant: Double = 9.81 // m/s^2
func airDensity(at altitude: Double) -> Double {
 let pressure = pressureAtSeaLevel * pow(1 - (0.0065 * altitude / temperatureAtSeaLevel), 5.2561)
 let temperature = temperatureAtSeaLevel - 0.0065 * altitude
 return (pressure * molecularMassOfAir) / (gasConstant * temperature)
}
func airResistanceCoefficient(for velocity: Double, at altitude: Double) -> Double {
 let density = airDensity(at: altitude)
 return (velocity * density * crossSectionalArea * dragCoefficient) / 2
}
func calculateProjectileMotion(for initialVelocity: Double, at angle: Double, from altitude: Double) -> (Double, Double) {
 let initialVelocityX = initialVelocity * cos(angle * Double.pi / 180)
 let initialVelocityY = initialVelocity * sin(angle * Double.pi / 180)
 var velocityX = initialVelocityX
 var velocityY = initialVelocityY
 var positionX: Double = 0
 var positionY = altitude
 var time: Double = 0
 let deltaTime: Double = 0.01

 while positionY >= altitude {
 let airResistanceCoefficient = airResistanceCoefficient(for: sqrt(pow(velocityX, 2) + pow(velocityY, 2)), at: positionY)
 let accelerationX = -airResistanceCoefficient * velocityX / initialVelocity - gravitationalConstant * sin(angle * Double.pi / 180)
 let accelerationY = -gravitationalConstant - airResistanceCoefficient * velocityY / initialVelocity
 velocityX += accelerationX * deltaTime
 velocityY += accelerationY * deltaTime
 positionX += velocityX * deltaTime
 positionY += velocityY * deltaTime
 time += deltaTime
 }

 return (positionX, time)
}
